contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function test(uint amount) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        uint before = address(this).balance;
        // InvMutTest has no payable fallback/receive, so this external call fails.
        // In P, the require(__sent_result100) makes sendMoney revert here.
        // In M, sendMoney silently continues.
        c.sendMoney(address(this), amount, ""); if (__ESBMC_reverted()) return;
        // Reached only in M: the failed call moved no ether, so the balance
        // cannot have grown by `amount` — the contract pretended a failed
        // transfer went through.
        assert(address(this).balance > before || amount == 0);
    }
}

