// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _test(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint before = address(this).balance;
        try c.sendMoney(address(this), amount, "") {} catch { return; }
        assertTrue(address(this).balance > before || amount == 0);
    }

    function testFuzz_test(uint256 amount) public {
        _test(amount);
    }

    receive() external payable {}
}
